    // apply to left child
    sum[2*node] = (b * sum[2*node] % MOD + c * (mid - l + 1) % MOD) % MOD;
    lb[2*node] = lb[2*node] * b % MOD;
    lc[2*node] = (b * lc[2*node] % MOD + c) % MOD;
    // apply to right child
