static ll mod_norm(ll x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return x;
}

static void apply(int idx, int len, ll b, ll c) {
    seg[idx].sum = (seg[idx].sum * b + c * len) % MOD;
    seg[idx].mul = seg[idx].mul * b % MOD;
    seg[idx].add = (seg[idx].add * b + c) % MOD;
}

static void push(int idx, int l, int r) {
    if (r - l == 1) return;
    if (seg[idx].mul == 1 && seg[idx].add == 0) return;
    int m = (l + r) >> 1;
    apply(idx << 1, m - l, seg[idx].mul, seg[idx].add);
    apply(idx << 1 | 1, r - m, seg[idx].mul, seg[idx].add);
    seg[idx].mul = 1;
    seg[idx].add = 0;
}

static void pull(int idx) {
    seg[idx].sum = (seg[idx << 1].sum + seg[idx << 1 | 1].sum) % MOD;
}

static void build(int idx, int l, int r, ll *a) {
    seg[idx].mul = 1;
    seg[idx].add = 0;
    if (r - l == 1) {
        seg[idx].sum = a[l] % MOD;
        return;
    }
    int m = (l + r) >> 1;
    build(idx << 1, l, m, a);
    build(idx << 1 | 1, m, r, a);
    pull(idx);
}

static void range_apply(int idx, int l, int r, int ql, int qr, ll b, ll c) {
    if (qr <= l || r <= ql) return;
    if (ql <= l && r <= qr) {
        apply(idx, r - l, b, c);
        return;
    }
    push(idx, l, r);
    int m = (l + r) >> 1;
    range_apply(idx << 1, l, m, ql, qr, b, c);
    range_apply(idx << 1 | 1, m, r, ql, qr, b, c);
    pull(idx);
}

static ll range_sum(int idx, int l, int r, int ql, int qr) {
    if (qr <= l || r <= ql) return 0;
    if (ql <= l && r <= qr) return seg[idx].sum;
    push(idx, l, r);
    int m = (l + r) >> 1;
    ll left = range_sum(idx << 1, l, m, ql, qr);
    ll right = range_sum(idx << 1 | 1, m, r, ql, qr);
    return (left + right) % MOD;
}

