        tree[child].sum = (b % MOD * tree[child].sum % MOD + c % MOD * tree[child].len % MOD) % MOD;
        tree[child].lb = b % MOD * tree[child].lb % MOD;
        tree[child].lc = (b % MOD * tree[child].lc % MOD + c % MOD) % MOD;
