static const long long MOD = 998244353;

struct LazySegTree {
    struct Node {
        long long sum;
        int len;
    };
    struct Tag {
        long long mul, add; // x -> mul * x + add
    };

    int n;
    vector<Node> seg;
    vector<Tag> lazy;

    LazySegTree(const vector<long long>& a) {
        int sz = (int)a.size();
        n = 1;
        while (n < sz) n <<= 1;
        seg.assign(2 * n, {0, 0});
        lazy.assign(2 * n, {1, 0});

        for (int i = 0; i < n; i++) {
            seg[n + i].len = 1;
            if (i < sz) seg[n + i].sum = a[i] % MOD;
        }
        for (int i = n - 1; i >= 1; i--) {
            seg[i].len = seg[i << 1].len + seg[i << 1 | 1].len;
            seg[i].sum = (seg[i << 1].sum + seg[i << 1 | 1].sum) % MOD;
        }
    }

    void apply(int p, long long mul, long long add) {
        seg[p].sum = (seg[p].sum * mul + add * seg[p].len) % MOD;
        lazy[p].mul = lazy[p].mul * mul % MOD;
        lazy[p].add = (lazy[p].add * mul + add) % MOD;
    }

    void push(int p) {
        if (lazy[p].mul != 1 || lazy[p].add != 0) {
            apply(p << 1, lazy[p].mul, lazy[p].add);
            apply(p << 1 | 1, lazy[p].mul, lazy[p].add);
            lazy[p] = {1, 0};
        }
    }

    void range_apply(int p, int l, int r, int ql, int qr, long long mul, long long add) {
        if (qr <= l || r <= ql) return;
        if (ql <= l && r <= qr) {
            apply(p, mul, add);
            return;
        }
        push(p);
        int m = (l + r) >> 1;
        range_apply(p << 1, l, m, ql, qr, mul, add);
        range_apply(p << 1 | 1, m, r, ql, qr, mul, add);
        seg[p].sum = (seg[p << 1].sum + seg[p << 1 | 1].sum) % MOD;
    }

    long long range_sum(int p, int l, int r, int ql, int qr) {
        if (qr <= l || r <= ql) return 0;
        if (ql <= l && r <= qr) return seg[p].sum;
        push(p);
        int m = (l + r) >> 1;
        return (range_sum(p << 1, l, m, ql, qr) + range_sum(p << 1 | 1, m, r, ql, qr)) % MOD;
    }

    void range_apply(int l, int r, long long mul, long long add) {
        range_apply(1, 0, n, l, r, mul % MOD, add % MOD);
    }

    long long range_sum(int l, int r) {
        return range_sum(1, 0, n, l, r);
    }
};

