MOD = 998244353


class LazySegTree:
    def __init__(self, arr):
        n = len(arr)
        size = 1
        while size < n:
            size <<= 1
        self.n = n
        self.size = size

        self.seg = [0] * (2 * size)
        # lazy affine transform: x -> mul * x + add
        self.lmul = [1] * (2 * size)
        self.ladd = [0] * (2 * size)

        for i in range(n):
            self.seg[size + i] = arr[i] % MOD
        for i in range(size - 1, 0, -1):
            self.seg[i] = (self.seg[i << 1] + self.seg[i << 1 | 1]) % MOD

    def _apply(self, k, mul, add, length):
        self.seg[k] = (self.seg[k] * mul + add * length) % MOD
        self.lmul[k] = self.lmul[k] * mul % MOD
        self.ladd[k] = (self.ladd[k] * mul + add) % MOD

    def _push(self, k, length):
        if self.lmul[k] == 1 and self.ladd[k] == 0:
            return
        half = length >> 1
        self._apply(k << 1, self.lmul[k], self.ladd[k], half)
        self._apply(k << 1 | 1, self.lmul[k], self.ladd[k], half)
        self.lmul[k] = 1
        self.ladd[k] = 0

    def range_apply(self, l, r, mul, add):
        self._range_apply(l, r, mul % MOD, add % MOD, 1, 0, self.size)

    def _range_apply(self, l, r, mul, add, k, sl, sr):
        if r <= sl or sr <= l:
            return
        if l <= sl and sr <= r:
            self._apply(k, mul, add, sr - sl)
            return
        self._push(k, sr - sl)
        mid = (sl + sr) >> 1
        self._range_apply(l, r, mul, add, k << 1, sl, mid)
        self._range_apply(l, r, mul, add, k << 1 | 1, mid, sr)
        self.seg[k] = (self.seg[k << 1] + self.seg[k << 1 | 1]) % MOD

    def range_sum(self, l, r):
        return self._range_sum(l, r, 1, 0, self.size)

    def _range_sum(self, l, r, k, sl, sr):
        if r <= sl or sr <= l:
            return 0
        if l <= sl and sr <= r:
            return self.seg[k]
        self._push(k, sr - sl)
        mid = (sl + sr) >> 1
        return (self._range_sum(l, r, k << 1, sl, mid) +
                self._range_sum(l, r, k << 1 | 1, mid, sr)) % MOD


def main():
    input = sys.stdin.readline
    N, Q = map(int, input().split())
