            sum[idx] = (b * sum[idx] + c * len) % MOD;
            lazyMul[idx] = (lazyMul[idx] * b) % MOD;
            lazyAdd[idx] = (lazyAdd[idx] * b + c) % MOD;
        }

        void push(int idx, int l, int r) {
            if (lazyMul[idx] != 1 || lazyAdd[idx] != 0) {
                int mid = (l + r) / 2;
                apply(idx * 2, l, mid, lazyMul[idx], lazyAdd[idx]);
                apply(idx * 2 + 1, mid, r, lazyMul[idx], lazyAdd[idx]);
                lazyMul[idx] = 1;
                lazyAdd[idx] = 0;
            }
        }

        void update(int idx, int l, int r, int ql, int qr, long b, long c) {
            if (ql >= r || qr <= l) return;
            if (ql <= l && r <= qr) {
                apply(idx, l, r, b, c);
                return;
            }
            push(idx, l, r);
            int mid = (l + r) / 2;
            update(idx * 2, l, mid, ql, qr, b, c);
            update(idx * 2 + 1, mid, r, ql, qr, b, c);
            sum[idx] = (sum[idx * 2] + sum[idx * 2 + 1]) % MOD;
        }

        long query(int idx, int l, int r, int ql, int qr) {
            if (ql >= r || qr <= l) return 0;
            if (ql <= l && r <= qr) return sum[idx];
            push(idx, l, r);
            int mid = (l + r) / 2;
            return (query(idx * 2, l, mid, ql, qr) + query(idx * 2 + 1, mid, r, ql, qr)) % MOD;
        }

        void rangeUpdate(int l, int r, long b, long c) {
            update(1, 0, n, l, r, b % MOD, c % MOD);
        }

        long rangeSum(int l, int r) {
            return query(1, 0, n, l, r);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        long[] arr = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            arr[i] = Long.parseLong(st.nextToken());
        }

        SegTree seg = new SegTree(N, arr);

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            if (type == 0) {
                int l = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                long b = Long.parseLong(st.nextToken());
                long c = Long.parseLong(st.nextToken());
                seg.rangeUpdate(l, r, b, c);
            } else {
                int l = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                sb.append(seg.rangeSum(l, r)).append("\n");
            }
        }
        System.out.print(sb);
    }
}

import java.util.*;
