public class Main {
    static final long MOD = 998244353;
    static long[] tree, lazyMul, lazyAdd;
    static int n;

    static void build(long[] a, int node, int l, int r) {
        lazyMul[node] = 1; lazyAdd[node] = 0;
        if (l + 1 == r) { tree[node] = a[l] % MOD; return; }
        int mid = (l + r) / 2;
        build(a, 2*node, l, mid);
        build(a, 2*node+1, mid, r);
        tree[node] = (tree[2*node] + tree[2*node+1]) % MOD;
    }

    static void pushDown(int node, int l, int r) {
        if (lazyMul[node] == 1 && lazyAdd[node] == 0) return;
        int mid = (l + r) / 2;
        applyLazy(2*node, l, mid, lazyMul[node], lazyAdd[node]);
        applyLazy(2*node+1, mid, r, lazyMul[node], lazyAdd[node]);
        lazyMul[node] = 1; lazyAdd[node] = 0;
    }

    static void applyLazy(int node, int l, int r, long mul, long add) {
        tree[node] = (mul * tree[node] + add * (r - l)) % MOD;
        lazyMul[node] = lazyMul[node] * mul % MOD;
        lazyAdd[node] = (lazyAdd[node] * mul + add) % MOD;
    }

    static void update(int node, int l, int r, int ql, int qr, long mul, long add) {
        if (qr <= l || r <= ql) return;
        if (ql <= l && r <= qr) { applyLazy(node, l, r, mul, add); return; }
        pushDown(node, l, r);
        int mid = (l + r) / 2;
        update(2*node, l, mid, ql, qr, mul, add);
        update(2*node+1, mid, r, ql, qr, mul, add);
        tree[node] = (tree[2*node] + tree[2*node+1]) % MOD;
    }

    static long query(int node, int l, int r, int ql, int qr) {
        if (qr <= l || r <= ql) return 0;
        if (ql <= l && r <= qr) return tree[node];
        pushDown(node, l, r);
        int mid = (l + r) / 2;
        return (query(2*node, l, mid, ql, qr) + query(2*node+1, mid, r, ql, qr)) % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
