import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class LazySegTree {
        int n, size, log;
        long[] sum;
        long[] mulLazy;
        long[] addLazy;

        LazySegTree(long[] a) {
            n = a.length;
            size = 1;
            log = 0;
            while (size < n) {
                size <<= 1;
                log++;
            }

            sum = new long[size << 1];
            mulLazy = new long[size];
            addLazy = new long[size];
            Arrays.fill(mulLazy, 1L);

            for (int i = 0; i < n; i++) sum[size + i] = mod(a[i]);
            for (int i = size - 1; i >= 1; i--) pull(i);
        }

        long mod(long x) {
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }

        void pull(int k) {
            sum[k] = sum[k << 1] + sum[k << 1 | 1];
            if (sum[k] >= MOD) sum[k] -= MOD;
        }

        void apply(int k, long mul, long add, int len) {
            sum[k] = (sum[k] * mul + add * len) % MOD;
            if (k < size) {
                mulLazy[k] = mulLazy[k] * mul % MOD;
                addLazy[k] = (addLazy[k] * mul + add) % MOD;
            }
        }

        void push(int k, int len) {
            if (mulLazy[k] == 1L && addLazy[k] == 0L) return;
            int half = len >> 1;
            apply(k << 1, mulLazy[k], addLazy[k], half);
            apply(k << 1 | 1, mulLazy[k], addLazy[k], half);
            mulLazy[k] = 1L;
            addLazy[k] = 0L;
        }

        void rangeApply(int l, int r, long mul, long add) {
            rangeApply(l, r, mod(mul), mod(add), 1, 0, size);
        }

        void rangeApply(int l, int r, long mul, long add, int k, int nl, int nr) {
            if (r <= nl || nr <= l) return;
            if (l <= nl && nr <= r) {
                apply(k, mul, add, nr - nl);
                return;
            }
            push(k, nr - nl);
            int mid = (nl + nr) >>> 1;
            rangeApply(l, r, mul, add, k << 1, nl, mid);
            rangeApply(l, r, mul, add, k << 1 | 1, mid, nr);
            pull(k);
        }

        long rangeSum(int l, int r) {
            return rangeSum(l, r, 1, 0, size);
        }

        long rangeSum(int l, int r, int k, int nl, int nr) {
            if (r <= nl || nr <= l) return 0;
            if (l <= nl && nr <= r) return sum[k];
            push(k, nr - nl);
            int mid = (nl + nr) >>> 1;
            long left = rangeSum(l, r, k << 1, nl, mid);
            long right = rangeSum(l, r, k << 1 | 1, mid, nr);
            long res = left + right;
            if (res >= MOD) res -= MOD;
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int N = fs.nextInt();
        int Q = fs.nextInt();

        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        LazySegTree seg = new LazySegTree(a);

        for (int qi = 0; qi < Q; qi++) {
            int t = fs.nextInt();
            if (t == 0) {
                int l = fs.nextInt();
                int r = fs.nextInt();
                long b = fs.nextLong();
                long c = fs.nextLong();
                seg.rangeApply(l, r, b, c);
            } else {
                int l = fs.nextInt();
                int r = fs.nextInt();
                out.append(seg.rangeSum(l, r)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}
